package composer

import (
	"fmt"
	"testing"

	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/weaviate/weaviate/entities/models"
	"github.com/weaviate/weaviate/usecases/config"
)

func Test_TokenAuthComposer(t *testing.T) {
	type test struct {
		name              string
		token             string
		config            config.Authentication
		namespacesEnabled bool
		oidc              TokenFunc
		apiKey            TokenFunc
		expectErr         bool
		expectErrMsg      string
	}

	tests := []test{
		{
			name: "everything disabled - returns generic error",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: false,
				},
				APIKey: config.StaticAPIKey{
					Enabled: false,
				},
			},
			token: "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				// We panic here to verify that the OIDC validator isnot called
				panic("i should never be called")
			},
			expectErr:    true,
			expectErrMsg: "no authentication scheme is configured",
		},
		{
			// This explicitly tests the scenario requested by the maintainer
			// "when no auth is enabled but token is provided"
			name: "everything disabled - generic error on invalid token",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: false,
				},
				APIKey: config.StaticAPIKey{
					Enabled: false,
				},
			},
			token: "some-token",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr:    true,
			expectErrMsg: "no authentication scheme is configured",
		},
		{
			name: "only oidc enabled, returns success",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: true,
				},
				APIKey: config.StaticAPIKey{
					Enabled: false,
				},
			},
			token: "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				return nil, nil
			},
			expectErr: false,
		},
		{
			name: "only oidc enabled, returns no success",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: true,
				},
				APIKey: config.StaticAPIKey{
					Enabled: false,
				},
			},
			token: "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				return nil, fmt.Errorf("thou shalt not pass")
			},
			expectErr:    true,
			expectErrMsg: "thou shalt not pass",
		},
		{
			name: "only apiKey enabled, returns success",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: false,
				},
				APIKey: config.StaticAPIKey{
					Enabled: true,
				},
			},
			token: "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return nil, nil
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr: false,
		},
		{
			name: "only apiKey enabled, returns no success",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: false,
				},
				APIKey: config.StaticAPIKey{
					Enabled: true,
				},
			},
			token: "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return nil, fmt.Errorf("you think I let anyone through?")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr:    true,
			expectErrMsg: "you think I let anyone through?",
		},
		{
			name: "both an enabled, with an 'obvious' api key",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: true,
				},
				APIKey: config.StaticAPIKey{
					Enabled: true,
				},
			},
			token: "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return nil, fmt.Errorf("it's a pretty key, but not good enough")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr:    true,
			expectErrMsg: "it's a pretty key, but not good enough",
		},
		{
			name: "both an enabled, empty token",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: true,
				},
				APIKey: config.StaticAPIKey{
					Enabled: true,
				},
			},
			token: "",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return nil, fmt.Errorf("really? an empty one?")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr:    true,
			expectErrMsg: "empty one",
		},
		{
			name: "both an enabled, jwt token",
			config: config.Authentication{
				OIDC: config.OIDC{
					Enabled: true,
				},
				APIKey: config.StaticAPIKey{
					Enabled: true,
				},
			},
			token: "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				return nil, fmt.Errorf("john doe ... that sounds like a fake name!")
			},
			expectErr:    true,
			expectErrMsg: "john doe",
		},
		{
			name: "namespaces enabled - rejects global non-operator principal",
			config: config.Authentication{
				APIKey: config.StaticAPIKey{Enabled: true},
			},
			namespacesEnabled: true,
			token:             "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return &models.Principal{Username: "drifted", Namespace: "", IsGlobalOperator: false}, nil
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr:    true,
			expectErrMsg: "neither namespace-confined nor a global operator",
		},
		{
			name: "namespaces enabled - allows global operator principal",
			config: config.Authentication{
				APIKey: config.StaticAPIKey{Enabled: true},
			},
			namespacesEnabled: true,
			token:             "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return &models.Principal{Username: "root", Namespace: "", IsGlobalOperator: true}, nil
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr: false,
		},
		{
			name: "namespaces enabled - allows namespace-confined principal",
			config: config.Authentication{
				APIKey: config.StaticAPIKey{Enabled: true},
			},
			namespacesEnabled: true,
			token:             "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return &models.Principal{Username: "ns-user", Namespace: "ns1", IsGlobalOperator: false}, nil
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr: false,
		},
		{
			name: "namespaces disabled - allows global non-operator principal",
			config: config.Authentication{
				APIKey: config.StaticAPIKey{Enabled: true},
			},
			namespacesEnabled: false,
			token:             "does not matter",
			apiKey: func(t string, s []string) (*models.Principal, error) {
				return &models.Principal{Username: "regular", Namespace: "", IsGlobalOperator: false}, nil
			},
			oidc: func(t string, s []string) (*models.Principal, error) {
				panic("i should never be called")
			},
			expectErr: false,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			v := New(
				test.config,
				test.namespacesEnabled,
				logrus.New(),
				fakeValidator{v: test.apiKey},
				fakeValidator{v: test.oidc},
			)
			_, err := v(test.token, nil)
			if test.expectErr {
				require.NotNil(t, err)
				assert.Contains(t, err.Error(), test.expectErrMsg)
				return
			}

			require.Nil(t, err)
		})
	}
}

type fakeValidator struct {
	v TokenFunc
}

func (v fakeValidator) ValidateAndExtract(t string, s []string) (*models.Principal, error) {
	return v.v(t, s)
}

