// TestMCPServerCollectionLevelAuthZ verifies that a user with MCP permission
// but only collection-scoped data permissions cannot access collections they
// are not authorized for via MCP tools (search, upsert, get-config).
func TestMCPServerCollectionLevelAuthZ(t *testing.T) {
	adminKey := "admin-key"
	customUser := "custom-user"
	customKey := "custom-key"

	compose, down := composeUpShared(t)
	defer down()

	mcpURL := fmt.Sprintf("http://%s", compose.GetWeaviate().McpURI())
	adminAuth := helper.CreateAuth(adminKey)

	// Create two collections: the user will only have access to AllowedCollection
	allowedClass := "AllowedCollection"
	forbiddenClass := "ForbiddenCollection"

	classProps := []*models.Property{
		{
			Name:     "content",
			DataType: schema.DataTypeText.PropString(),
		},
	}
	for _, className := range []string{allowedClass, forbiddenClass} {
		helper.DeleteClassWithAuthz(t, className, adminAuth)
		helper.CreateClassAuth(t, &models.Class{
			Class:      className,
			Properties: classProps,
			Vectorizer: "none",
		}, adminKey)
	}
	defer helper.DeleteClassWithAuthz(t, allowedClass, adminAuth)
	defer helper.DeleteClassWithAuthz(t, forbiddenClass, adminAuth)

	// Insert an object into each collection as admin
	for _, className := range []string{allowedClass, forbiddenClass} {
		require.NoError(t, helper.CreateObjectAuth(t, &models.Object{
			Class: className,
			Properties: map[string]interface{}{
				"content": "test content for " + className,
			},
		}, adminKey))
	}

	// Create a role with MCP read + update permissions + data permissions scoped to AllowedCollection only
	roleName := "collection-scoped-mcp-role"
	helper.DeleteRole(t, adminKey, roleName)
	helper.CreateRole(t, adminKey, &models.Role{
		Name: &roleName,
		Permissions: []*models.Permission{
			{
				Action: &authorization.CreateMcp,
			},
			{
				Action: &authorization.ReadMcp,
			},
			{
				Action: &authorization.UpdateMcp,
			},
			{
				Action: &authorization.ReadCollections,
				Collections: &models.PermissionCollections{
					Collection: &allowedClass,
				},
			},
			{
				Action: &authorization.ReadData,
				Data: &models.PermissionData{
					Collection: &allowedClass,
				},
			},
			{
				Action: &authorization.CreateData,
				Data: &models.PermissionData{
					Collection: &allowedClass,
				},
			},
			{
				Action: &authorization.UpdateData,
				Data: &models.PermissionData{
					Collection: &allowedClass,
				},
			},
		},
	})
	defer helper.DeleteRole(t, adminKey, roleName)
	helper.AssignRoleToUser(t, adminKey, roleName, customUser)
	defer helper.RevokeRoleFromUser(t, adminKey, roleName, customUser)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	// Use alpha=0 (pure keyword/BM25) to avoid vectorizer requirement since classes use vectorizer: none
	pureKeyword := float64(0)

	t.Run("hybrid search on allowed collection succeeds", func(t *testing.T) {
		var resp search.QueryHybridResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-query-hybrid", customKey,
			search.QueryHybridArgs{
				Query:          "test",
				CollectionName: allowedClass,
				Alpha:          &pureKeyword,
			}, &resp)
		require.NoError(t, err)
	})

	t.Run("hybrid search on forbidden collection fails with auth error", func(t *testing.T) {
		var resp search.QueryHybridResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-query-hybrid", customKey,
			search.QueryHybridArgs{
				Query:          "test",
				CollectionName: forbiddenClass,
				Alpha:          &pureKeyword,
			}, &resp)
		require.Error(t, err)
		require.Contains(t, err.Error(), "forbidden")
	})

	t.Run("upsert into allowed collection succeeds", func(t *testing.T) {
		var resp create.UpsertObjectResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-objects-upsert", customKey,
			create.UpsertObjectArgs{
				CollectionName: allowedClass,
				Objects: []create.ObjectToUpsert{
					{Properties: map[string]any{"content": "new object"}},
				},
			}, &resp)
		require.NoError(t, err)
		require.Len(t, resp.Results, 1)
		require.Empty(t, resp.Results[0].Error)
		require.NotEmpty(t, resp.Results[0].ID)
	})

	t.Run("upsert into forbidden collection fails", func(t *testing.T) {
		var resp create.UpsertObjectResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-objects-upsert", customKey,
			create.UpsertObjectArgs{
				CollectionName: forbiddenClass,
				Objects: []create.ObjectToUpsert{
					{Properties: map[string]any{"content": "should not be allowed"}},
				},
			}, &resp)
		require.Error(t, err)
		require.Contains(t, err.Error(), "forbidden")
	})

	t.Run("get-config for allowed collection succeeds", func(t *testing.T) {
		var resp read.GetCollectionConfigResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-collections-get-config", customKey,
			read.GetCollectionConfigArgs{CollectionName: allowedClass}, &resp)
		require.NoError(t, err)
		require.Len(t, resp.Collections, 1)
		require.Equal(t, allowedClass, resp.Collections[0].Class)
	})

	t.Run("get-config for forbidden collection is not visible", func(t *testing.T) {
		var resp read.GetCollectionConfigResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-collections-get-config", customKey,
			read.GetCollectionConfigArgs{CollectionName: forbiddenClass}, &resp)
		// The schema reader filters by auth, so the collection is simply not found
		// (information hiding — user doesn't learn the collection exists)
		require.Error(t, err)
		require.Contains(t, err.Error(), "not found")
	})

	t.Run("get-config for all collections only returns allowed", func(t *testing.T) {
		var resp read.GetCollectionConfigResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-collections-get-config", customKey,
			read.GetCollectionConfigArgs{}, &resp)
		require.NoError(t, err)
		// Should only see AllowedCollection, not ForbiddenCollection
		for _, c := range resp.Collections {
			require.NotEqual(t, forbiddenClass, c.Class,
				"user should not see ForbiddenCollection in unfiltered get-config response")
		}
	})
}

// TestMCPPermissionSeparation verifies that read_mcp and update_mcp permissions
// are enforced independently: a read-only user cannot upsert, and a write-only
// user cannot search or list collections.
func TestMCPPermissionSeparation(t *testing.T) {
	adminKey := "admin-key"
	readUser := "read-user"
	readKey := "read-key"
	writeUser := "write-user"
	writeKey := "write-key"

	compose, down := composeUpShared(t)
	defer down()

	mcpURL := fmt.Sprintf("http://%s", compose.GetWeaviate().McpURI())
	adminAuth := helper.CreateAuth(adminKey)

	// Create a test collection
	className := "PermTestCollection"
	helper.DeleteClassWithAuthz(t, className, adminAuth)
	helper.CreateClassAuth(t, &models.Class{
		Class: className,
		Properties: []*models.Property{
			{Name: "content", DataType: schema.DataTypeText.PropString()},
		},
		Vectorizer: "none",
	}, adminKey)
	defer helper.DeleteClassWithAuthz(t, className, adminAuth)

	// Insert test data as admin
	require.NoError(t, helper.CreateObjectAuth(t, &models.Object{
		Class:      className,
		Properties: map[string]interface{}{"content": "test content"},
	}, adminKey))

	// Create read-only role: read_mcp + read_collections + read_data
	readRole := "mcp-read-only-role"
	helper.DeleteRole(t, adminKey, readRole)
	helper.CreateRole(t, adminKey, &models.Role{
		Name: &readRole,
		Permissions: []*models.Permission{
			{Action: &authorization.ReadMcp},
			{Action: &authorization.ReadCollections, Collections: &models.PermissionCollections{Collection: &className}},
			{Action: &authorization.ReadData, Data: &models.PermissionData{Collection: &className}},
		},
	})
	defer helper.DeleteRole(t, adminKey, readRole)
	helper.AssignRoleToUser(t, adminKey, readRole, readUser)
	defer helper.RevokeRoleFromUser(t, adminKey, readRole, readUser)

	// Create write-only role: update_mcp + create_data + update_data
	writeRole := "mcp-write-only-role"
	helper.DeleteRole(t, adminKey, writeRole)
	helper.CreateRole(t, adminKey, &models.Role{
		Name: &writeRole,
		Permissions: []*models.Permission{
			{Action: &authorization.CreateMcp},
			{Action: &authorization.UpdateMcp},
			{Action: &authorization.CreateData, Data: &models.PermissionData{Collection: &className}},
			{Action: &authorization.UpdateData, Data: &models.PermissionData{Collection: &className}},
		},
	})
	defer helper.DeleteRole(t, adminKey, writeRole)
	helper.AssignRoleToUser(t, adminKey, writeRole, writeUser)
	defer helper.RevokeRoleFromUser(t, adminKey, writeRole, writeUser)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	pureKeyword := float64(0)

	// --- Read-only user tests ---

	t.Run("read user can call get-config", func(t *testing.T) {
		var resp read.GetCollectionConfigResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-collections-get-config", readKey,
			read.GetCollectionConfigArgs{CollectionName: className}, &resp)
		require.NoError(t, err)
		require.Len(t, resp.Collections, 1)
	})

	t.Run("read user can call hybrid search", func(t *testing.T) {
		var resp search.QueryHybridResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-query-hybrid", readKey,
			search.QueryHybridArgs{
				Query:          "test",
				CollectionName: className,
				Alpha:          &pureKeyword,
			}, &resp)
		require.NoError(t, err)
	})

	t.Run("read user cannot call upsert", func(t *testing.T) {
		var resp create.UpsertObjectResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-objects-upsert", readKey,
			create.UpsertObjectArgs{
				CollectionName: className,
				Objects: []create.ObjectToUpsert{
					{Properties: map[string]any{"content": "should fail"}},
				},
			}, &resp)
		require.Error(t, err)
		require.Contains(t, err.Error(), "forbidden")
	})

	// --- Write-only user tests ---

	t.Run("write user cannot call get-config", func(t *testing.T) {
		var resp read.GetCollectionConfigResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-collections-get-config", writeKey,
			read.GetCollectionConfigArgs{CollectionName: className}, &resp)
		require.Error(t, err)
		require.Contains(t, err.Error(), "forbidden")
	})

	t.Run("write user cannot call hybrid search", func(t *testing.T) {
		var resp search.QueryHybridResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-query-hybrid", writeKey,
			search.QueryHybridArgs{
				Query:          "test",
				CollectionName: className,
				Alpha:          &pureKeyword,
			}, &resp)
		require.Error(t, err)
		require.Contains(t, err.Error(), "forbidden")
	})

	t.Run("write user can call upsert", func(t *testing.T) {
		var resp create.UpsertObjectResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-objects-upsert", writeKey,
			create.UpsertObjectArgs{
				CollectionName: className,
				Objects: []create.ObjectToUpsert{
					{Properties: map[string]any{"content": "write user object"}},
				},
			}, &resp)
		require.NoError(t, err)
		require.Len(t, resp.Results, 1)
		require.Empty(t, resp.Results[0].Error)
		require.NotEmpty(t, resp.Results[0].ID)
	})
}

// TestMCPTenantsListAuthZ pins down that weaviate-tenants-list only requires
// read_mcp + read_tenants — not read_data. A pre-fix CollectionsData
// pre-check would have denied the read_tenants-only role.
func TestMCPTenantsListAuthZ(t *testing.T) {
	adminKey := "admin-key"
	tenantReadUser := "tenant-read-user"
	tenantReadKey := "tenant-read-key"
	mcpOnlyUser := "mcp-only-user"
	mcpOnlyKey := "mcp-only-key"

	compose, down := composeUpShared(t)
	defer down()

	mcpURL := fmt.Sprintf("http://%s", compose.GetWeaviate().McpURI())
	adminAuth := helper.CreateAuth(adminKey)

	className := "MTTenantsListAuthZ"
	allTenants := "*"
	helper.DeleteClassWithAuthz(t, className, adminAuth)
	helper.CreateClassAuth(t, &models.Class{
		Class:              className,
		Properties:         []*models.Property{{Name: "content", DataType: schema.DataTypeText.PropString()}},
		Vectorizer:         "none",
		MultiTenancyConfig: &models.MultiTenancyConfig{Enabled: true},
	}, adminKey)
	defer helper.DeleteClassWithAuthz(t, className, adminAuth)

	helper.CreateTenantsAuth(t, className, []*models.Tenant{
		{Name: "t1", ActivityStatus: models.TenantActivityStatusHOT},
		{Name: "t2", ActivityStatus: models.TenantActivityStatusHOT},
	}, adminKey)

	// read_mcp + read_tenants on the class, no read_data
	tenantReadRole := "mcp-tenant-read-role"
	helper.DeleteRole(t, adminKey, tenantReadRole)
	helper.CreateRole(t, adminKey, &models.Role{
		Name: &tenantReadRole,
		Permissions: []*models.Permission{
			{Action: &authorization.ReadMcp},
			{
				Action:  &authorization.ReadTenants,
				Tenants: &models.PermissionTenants{Collection: &className, Tenant: &allTenants},
			},
		},
	})
	defer helper.DeleteRole(t, adminKey, tenantReadRole)
	helper.AssignRoleToUser(t, adminKey, tenantReadRole, tenantReadUser)
	defer helper.RevokeRoleFromUser(t, adminKey, tenantReadRole, tenantReadUser)

	// read_mcp only — no read_tenants
	mcpOnlyRole := "mcp-only-role"
	helper.DeleteRole(t, adminKey, mcpOnlyRole)
	helper.CreateRole(t, adminKey, &models.Role{
		Name: &mcpOnlyRole,
		Permissions: []*models.Permission{
			{Action: &authorization.ReadMcp},
		},
	})
	defer helper.DeleteRole(t, adminKey, mcpOnlyRole)
	helper.AssignRoleToUser(t, adminKey, mcpOnlyRole, mcpOnlyUser)
	defer helper.RevokeRoleFromUser(t, adminKey, mcpOnlyRole, mcpOnlyUser)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	t.Run("read_mcp + read_tenants (no read_data) lists tenants", func(t *testing.T) {
		var resp read.GetTenantsResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-tenants-list", tenantReadKey,
			read.GetTenantsArgs{CollectionName: className}, &resp)
		require.NoError(t, err)
		names := make([]string, 0, len(resp.Tenants))
		for _, tn := range resp.Tenants {
			names = append(names, tn.Name)
		}
		require.ElementsMatch(t, []string{"t1", "t2"}, names)
	})

	t.Run("read_mcp without read_tenants returns no tenants", func(t *testing.T) {
		var resp read.GetTenantsResp
		err := callToolOnceWithAuth(ctx, t, mcpURL, "weaviate-tenants-list", mcpOnlyKey,
			read.GetTenantsArgs{CollectionName: className}, &resp)
		require.NoError(t, err)
		require.Empty(t, resp.Tenants)
	})
}

