			"roles/.*",
			"customer1",
			false,
		},
		{
			"ns=customer1, cross-ns role, roles/.* policy → mismatch (cross-ns deny)",
			"roles/customer2:editor",
			"roles/.*",
			"customer1",
			false,
		},
		{
			"ns=customer1, exact qualified role policy → match",
			"roles/customer1:editor",
			"roles/customer1:editor",
			"customer1",
			true,
		},
		{
			"empty ns, qualified role, roles/.* policy → match (any-ns widen)",
			"roles/customer1:editor",
			"roles/.*",
			"",
			true,
		},
		{
			"empty ns, qualified role, literal roles/* policy → match (/* normalized)",
			"roles/customer1:editor",
			"roles/*",
			"",
			true,
		},
		{
			"empty ns, unqualified role, roles/.* policy → passthrough match (operator unchanged)",
			"roles/editor",
			"roles/.*",
			"",
			true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			testNamespaceAwareMatcher(t, tt.reqObj, tt.polObj, tt.ns, tt.expected)
		})
	}
}

// TestNamespaceAwareMatcher_ColonBearingGlobalUser: a global caller (ns == "")
// may carry a user id containing ':'. The matcher must match users/<id>
// literally — else such ids are falsely denied a wildcard grant, or falsely
// matched against a grant to a different user.
func TestNamespaceAwareMatcher_ColonBearingGlobalUser(t *testing.T) {
	tests := []struct {
		name     string
		reqObj   string
		polObj   string
		ns       string
		expected bool
	}{
		{
			"baseline: no colon, wildcard grant → allow",
			"users/alice", "users/.*", "", true,
		},
		{
			"colon in id must not break a wildcard grant → allow",
			"users/urn:foo", "users/.*", "", true,
		},
		{
			"leading colon must not break a wildcard grant → allow",
			"users/:foo", "users/.*", "", true,
		},
		{
			"trailing colon must not break a wildcard grant → allow",
			"users/foo:", "users/.*", "", true,
		},
		{
			"multi-colon id must not break a wildcard grant → allow",
			"users/a:b:c", "users/.*", "", true,
		},
		{
			"literal /* wildcard normalizes and still matches colon id → allow",
			"users/customer1:alice", "users/*", "", true,
		},
		{
			"root's bare * grant still matches colon id → allow",
			"users/customer1:alice", "*", "", true,
		},
		{
			"narrower grant to user 'a' must NOT widen to id 'x:a' → deny",
			"users/x:a", "users/a", "", false,
		},
		{
			"narrower grant to user 'alice' must NOT widen to id 'customer1:alice' → deny",
			"users/customer1:alice", "users/alice", "", false,
		},
		{
			"exact-match grant to a colon id → allow",
			"users/customer1:alice", "users/customer1:alice", "", true,
		},
		{
			"namespaced caller still specializes a relative user grant → allow",
			"users/customer1:alice", "users/alice", "customer1", true,
		},
		{
			"namespaced caller is denied a cross-namespace user → deny",
			"users/customer2:alice", "users/alice", "customer1", false,
		},
		{
			"colon in a group name is opaque too: exact grant → allow",
			"groups/oidc/team:eng", "groups/oidc/team:eng", "", true,
		},
		{
			"colon in a group name must not widen to a different group → deny",
			"groups/oidc/team:eng", "groups/oidc/team:other", "", false,
		},
		{
			"regression guard: collection widening for a global caller still works → allow",
			"schema/collections/customer1:Movies/shards/#", conv.CasbinSchema("Movies*", "#"), "", true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			testNamespaceAwareMatcher(t, tt.reqObj, tt.polObj, tt.ns, tt.expected)
		})
	}
}

// TestNamespaceAwareMatcherGate locks the namespacesEnabled gate: on
// namespace-disabled clusters the matcher must not parse ':' as a namespace
// prefix, because an OIDC username may legitimately contain ':' there
// (oidc/middleware.go rejects ':' only when namespaces are enabled).
func TestNamespaceAwareMatcherGate(t *testing.T) {
	call := func(namespacesEnabled bool, reqObj, polObj, ns string) bool {
		t.Helper()
		got, err := makeNamespaceAwareMatcherFunc(namespacesEnabled)(reqObj, polObj, ns)
		require.NoError(t, err)
		return got.(bool)
	}

	// NS-disabled: a grant to user "a" must NOT broaden to OIDC user "x:a".
	assert.False(t, call(false, "users/x:a", "users/a", ""),
		"NS-disabled: grant to user 'a' must not match OIDC user 'x:a'")
	assert.True(t, call(false, "users/bob", "users/.*", ""),
		"NS-disabled: plain wildcard match still works")
	assert.True(t, call(false, "schema/collections/Movies/shards/#", conv.CasbinSchema("Movies", "#"), ""),
		"NS-disabled: collection matching unchanged")

	// NS-enabled global caller (ns == "") matches user ids literally: a grant to
	// "a" must not widen to OIDC user "x:a".
	assert.False(t, namespaceAwareMatcher("users/x:a", "users/a", ""),
		"NS-enabled global caller: grant to user 'a' must not match OIDC user 'x:a'")

	// NS-disabled: roles/ mirrors users/ — grant to 'foo' must not match 'x:foo'.
	assert.False(t, call(false, "roles/x:foo", "roles/foo", ""),
		"NS-disabled: grant to role 'foo' must not match 'x:foo'")
	assert.True(t, call(false, "roles/editor", "roles/.*", ""),
		"NS-disabled: plain wildcard role match still works")

	// NS-enabled: the gate delegates to the namespace-aware core.
	assert.True(t, call(true, "users/customer1:bob", "users/.*", "customer1"),
		"NS-enabled: users/.* specializes to the caller's namespace")
	assert.False(t, call(true, "users/customer2:bob", "users/.*", "customer1"),
		"NS-enabled: cross-namespace user access denied")
	// Operator-only domains are denied to namespaced callers (ns != "") even
	// when a delegated role's wildcard policy would otherwise match, but stay
	// reachable for the global caller (ns == "").
	for _, dom := range []string{"backups", "nodes", "replicate", "cluster", "namespaces", "groups"} {
		req := dom + "/anything"
		assert.False(t, namespaceAwareMatcher(req, dom+"/.*", "customer1"),
			"namespaced caller must be denied operator-only domain %q", dom)
		assert.True(t, namespaceAwareMatcher(req, dom+"/.*", ""),
			"global caller must reach operator-only domain %q", dom)
	}
	// Groups are global, not namespace-bearing: a namespaced caller must not
	// match a groups/ policy even when the group id itself carries a ':'.
	assert.False(t, namespaceAwareMatcher("groups/oidc/customer1:admins", "groups/.*", "customer1"),
		"namespaced caller must be denied groups/ even for a colon-bearing group id")

	// roles is namespace-bearing via qualified names, so the gate must not
	// blanket-deny it for namespaced callers.
	assert.True(t, call(true, "roles/customer1:editor", "roles/.*", "customer1"),
		"NS-enabled: roles/.* specializes to the caller's namespace")
	assert.False(t, call(true, "roles/customer2:editor", "roles/.*", "customer1"),
		"NS-enabled: cross-namespace role access denied")
}

// TestRewritePolicy asserts the exact rewritten string for representative
// schema/data/aliases shapes and the cross-namespace deny path on both the
// collection and alias segment.
func TestRewritePolicy(t *testing.T) {
	tests := []struct {
		name     string
		policy   string
		prefix   string
		fixedNs  bool
		wantOK   bool
		wantText string
	}{
		{
			name:     "schema path, fixed-ns specialize, unqualified col",
			policy:   "schema/collections/Movies.*/shards/#",
			prefix:   "customer1:",
			fixedNs:  true,
			wantOK:   true,
			wantText: "schema/collections/customer1:Movies.*/shards/#",
		},
		{
			name:     "data path, fixed-ns specialize, unqualified col",
			policy:   "data/collections/Movies.*/shards/.*/objects/.*",
			prefix:   "customer1:",
			fixedNs:  true,
			wantOK:   true,
			wantText: "data/collections/customer1:Movies.*/shards/.*/objects/.*",
		},
		{
			name:     "data path, any-ns widen, unqualified col",
			policy:   "data/collections/Movies.*/shards/.*/objects/.*",
			prefix:   anyNamespacePattern,
			fixedNs:  false,
			wantOK:   true,
			wantText: "data/collections/[^/:]+:Movies.*/shards/.*/objects/.*",
		},
		{
			name:     "schema path, any-ns widen, unqualified col",
			policy:   "schema/collections/Movies.*/shards/#",
			prefix:   anyNamespacePattern,
			fixedNs:  false,
			wantOK:   true,
			wantText: "schema/collections/[^/:]+:Movies.*/shards/#",
		},
		{
			name:     "schema path, fixed-ns, already-qualified matching col → policy unchanged",
			policy:   "schema/collections/customer1:Movies/shards/#",
			prefix:   "customer1:",
			fixedNs:  true,
			wantOK:   true,
			wantText: "schema/collections/customer1:Movies/shards/#",
		},
		{
			name:    "schema path, fixed-ns, already-qualified mismatching col → cross-NS deny",
			policy:  "schema/collections/customer2:Movies/shards/#",
			prefix:  "customer1:",
			fixedNs: true,
			wantOK:  false,
		},
		{
			name:     "aliases path, fixed-ns specialize, both segs unqualified",
			policy:   "aliases/collections/Movies/aliases/Films",
			prefix:   "customer1:",
			fixedNs:  true,
			wantOK:   true,
			wantText: "aliases/collections/customer1:Movies/aliases/customer1:Films",
		},
		{
			name:     "aliases path, any-ns widen, both segs unqualified",
			policy:   "aliases/collections/Movies/aliases/Films",
			prefix:   anyNamespacePattern,
			fixedNs:  false,
			wantOK:   true,
			wantText: "aliases/collections/[^/:]+:Movies/aliases/[^/:]+:Films",
		},
		{
			name:    "aliases path, fixed-ns, qualified alias names different NS → cross-NS deny on second segment",
			policy:  "aliases/collections/customer1:Movies/aliases/customer2:Films",
			prefix:  "customer1:",
			fixedNs: true,
			wantOK:  false,
		},
		{
			name:     "roles path, fixed-ns specialize, unqualified role",
			policy:   "roles/.*",
			prefix:   "customer1:",
			fixedNs:  true,
			wantOK:   true,
			wantText: "roles/customer1:.*",
		},
		{
			name:     "roles path, fixed-ns, already-qualified matching role → policy unchanged",
			policy:   "roles/customer1:editor",
			prefix:   "customer1:",
			fixedNs:  true,
			wantOK:   true,
			wantText: "roles/customer1:editor",
		},
		{
			name:    "roles path, fixed-ns, already-qualified mismatching role → cross-NS deny",
			policy:  "roles/customer2:editor",
			prefix:  "customer1:",
			fixedNs: true,
			wantOK:  false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, colEnd, _ := namespacing.FindNamespaceSegments(tt.policy); colEnd == 0 {
				t.Fatalf("test setup: %q is not namespaceable", tt.policy)
			}
			got, ok := rewritePolicy(tt.policy, tt.prefix, tt.fixedNs)
			if ok != tt.wantOK {
				t.Fatalf("rewritePolicy ok = %v; want %v (got=%q)", ok, tt.wantOK, got)
			}
			if ok && got != tt.wantText {
				t.Errorf("rewritePolicy = %q; want %q", got, tt.wantText)
			}
		})
	}
}

// freshPolicyDir creates a per-test rbac storage directory. Sets a
// sentinel build.Version so re-Init against the same directory parses
// the version file (empty build.Version corrupts it).
func freshPolicyDir(t *testing.T) string {
	t.Helper()
	tmp, err := os.MkdirTemp("", "rbac-init-*")
	require.NoError(t, err)
	t.Cleanup(func() { os.RemoveAll(tmp) })
	if build.Version == "" {
		build.Version = "1.30.0"
	}
	return tmp
}

// rolePolicies returns the resource/verb/domain rows currently registered for
// roleName.
func rolePolicies(t *testing.T, m *Manager, roleName string) [][]string {
	t.Helper()
	rows, err := m.casbin.GetFilteredNamedPolicy("p", 0, conv.PrefixRoleName(roleName))
	require.NoError(t, err)
	return rows
}

// roleHasResourceVerb reports whether roleName has any policy with a
// matching resource pattern and verb.
func roleHasResourceVerb(rows [][]string, resourceContains, verb string) bool {
	for _, r := range rows {
		if strings.Contains(r[1], resourceContains) && r[2] == verb {
			return true
		}
	}
	return false
}

// TestApplyPredefinedRoles_NamespacesEnabled_AdminViewerNarrowed asserts
// admin/viewer on NS-enabled clusters cover only collections/data/tenants/
// aliases plus MCP, user CRUD + assign/revoke, and MATCH-scoped roles
// management (admin CRUD, viewer READ).
func TestApplyPredefinedRoles_NamespacesEnabled_AdminViewerNarrowed(t *testing.T) {
	dir := freshPolicyDir(t)
	conf := rbacconf.Config{Enabled: true}
	enforcer, err := Init(conf, dir, config.Authentication{}, true)
	require.NoError(t, err)
	require.NotNil(t, enforcer)

	m := &Manager{casbin: enforcer, namespacesEnabled: true}

	adminRows := rolePolicies(t, m, authorization.Admin)
	viewerRows := rolePolicies(t, m, authorization.Viewer)
	rootRows := rolePolicies(t, m, authorization.Root)
	readOnlyRows := rolePolicies(t, m, authorization.ReadOnly)

	// admin: must contain CRUD over schema/data/aliases plus MCP, user CRUD +
	// assign/revoke, and roles CRUD at MATCH scope; tenant rows share the schema
	// domain. No backups/replicate/cluster/nodes/groups/namespaces.
	assert.True(t, roleHasResourceVerb(adminRows, "schema/collections/", authorization.CREATE))
	assert.True(t, roleHasResourceVerb(adminRows, "schema/collections/", authorization.READ))
	assert.True(t, roleHasResourceVerb(adminRows, "schema/collections/", authorization.UPDATE))
	assert.True(t, roleHasResourceVerb(adminRows, "schema/collections/", authorization.DELETE))
	assert.True(t, roleHasResourceVerb(adminRows, "data/collections/", authorization.READ))
	assert.True(t, roleHasResourceVerb(adminRows, "aliases/collections/", authorization.READ))
	assert.True(t, roleHasResourceVerb(adminRows, conv.CasbinMcp(), authorization.CREATE))
	assert.True(t, roleHasResourceVerb(adminRows, conv.CasbinMcp(), authorization.READ))
	assert.True(t, roleHasResourceVerb(adminRows, conv.CasbinMcp(), authorization.UPDATE))
	assert.True(t, roleHasResourceVerb(adminRows, "users/", authorization.CREATE))
	assert.True(t, roleHasResourceVerb(adminRows, "users/", authorization.READ))
	assert.True(t, roleHasResourceVerb(adminRows, "users/", authorization.UPDATE))
	assert.True(t, roleHasResourceVerb(adminRows, "users/", authorization.DELETE))
	for _, prohibited := range []string{
		"backups/", "cluster/", "nodes/", "groups/", "namespaces/", "replicate/",
	} {
		for _, row := range adminRows {
			assert.NotContains(t, row[1], prohibited, "admin (NS-enabled) must not have policy on %s domain", prohibited)
		}
	}
	// AssignAndRevokeUsers (verb "A" on users/) is included.
	assert.True(t, roleHasResourceVerb(adminRows, "users/", authorization.USER_AND_GROUP_ASSIGN_AND_REVOKE),
		"admin (NS-enabled) must have assign_and_revoke_users")
	// roles management is included, but only at MATCH scope — never ALL.
	for _, verb := range []string{authorization.CREATE, authorization.READ, authorization.UPDATE, authorization.DELETE} {
		assert.True(t, roleHasResourceVerb(adminRows, "roles/", authorization.VerbWithScope(verb, authorization.ROLE_SCOPE_MATCH)),
			"admin (NS-enabled) must have roles %s at MATCH scope", verb)
		assert.False(t, roleHasResourceVerb(adminRows, "roles/", authorization.VerbWithScope(verb, authorization.ROLE_SCOPE_ALL)),
			"admin (NS-enabled) must not have ALL-scoped roles %s", verb)
	}

	// viewer: read-only over the same domains, no write verbs. MCP, users and
	// roles are included as READ only (roles READ is MATCH-scoped).
	for _, row := range viewerRows {
		base, _, _ := strings.Cut(row[2], "_")
		assert.Equal(t, authorization.READ, base, "viewer (NS-enabled) must only have READ verb (any scope)")
	}
	assert.True(t, roleHasResourceVerb(viewerRows, "schema/collections/", authorization.READ))
	assert.True(t, roleHasResourceVerb(viewerRows, "data/collections/", authorization.READ))
	assert.True(t, roleHasResourceVerb(viewerRows, conv.CasbinMcp(), authorization.READ))
	assert.True(t, roleHasResourceVerb(viewerRows, "users/", authorization.READ))
	assert.True(t, roleHasResourceVerb(viewerRows, "roles/", authorization.VerbWithScope(authorization.READ, authorization.ROLE_SCOPE_MATCH)),
		"viewer (NS-enabled) must have roles READ at MATCH scope")

	// root and read-only keep wildcard cluster-wide policies.
	require.Len(t, rootRows, 1)
	assert.Equal(t, []string{conv.PrefixRoleName(authorization.Root), "*", conv.VALID_VERBS, "*"}, rootRows[0])
	require.Len(t, readOnlyRows, 1)
	assert.Equal(t, []string{conv.PrefixRoleName(authorization.ReadOnly), "*", authorization.READ, "*"}, readOnlyRows[0])
}

// TestApplyPredefinedRoles_RestartSurvivesAPIAssignment_NSDisabled is the
// NS-disabled control: the policy wipe-and-rebuild on every Init must not
// touch user→role groupings created via the API.
func TestApplyPredefinedRoles_RestartSurvivesAPIAssignment_NSDisabled(t *testing.T) {
	dir := freshPolicyDir(t)
	conf := rbacconf.Config{Enabled: true}

	enforcer, err := Init(conf, dir, config.Authentication{}, false)
	require.NoError(t, err)

	// API-assign admin to a DB user.
	user := conv.UserNameWithTypeFromId("alice", authentication.AuthTypeDb)
	_, err = enforcer.AddRoleForUser(user, conv.PrefixRoleName(authorization.Admin))
	require.NoError(t, err)
	require.NoError(t, enforcer.SavePolicy())

	// Simulate a restart: re-Init against the same on-disk policy CSV.
	enforcer2, err := Init(conf, dir, config.Authentication{}, false)
	require.NoError(t, err)

	roles, err := enforcer2.GetRolesForUser(user)
	require.NoError(t, err)
	assert.Contains(t, roles, conv.PrefixRoleName(authorization.Admin),
		"API-assigned admin grouping must survive restart on NS-disabled")
}

